edits.new:
const SPEC_LEVEL = ARMS_HERO_MODE ? 15 : 10;
const PET_SELECTION_LEVEL = 10;
/* SPEC15_BEGIN */
function selectedSpec(k) {
  const c = B.CLASSES[clsOf(k)], g = tavRec(k);
  if (!c) return null;
  const selected = g ? g.sp : S.specs[k];
  return c.specs[selected] ? selected : c.def;
}
function canSpecialize(k) {
  return !!B.CLASSES[clsOf(k)] && (hLevel(k) >= SPEC_LEVEL || (!ARMS_HERO_MODE && S.allSpecs));
}
function runtimeLeaderAura(party) {
  if (ARMS_HERO_MODE && S.hero && hLevel('me') < SPEC_LEVEL) return { res: [] };
  return B.leaderAura(party);
}
/* SPEC15_END */

function effectiveSpec(c) {
  const sp = c && c.specs && c.specs.me, cl = c && B.CLASSES[c.cls];
  if (!cl) return null;
  const level = ARMS_HERO_MODE && c.hxp && Number.isFinite(c.hxp.me) ? B.levelOf(c.hxp.me) : c.level;
  if (ARMS_HERO_MODE && level < SPEC_LEVEL) return null;
  if (!ARMS_HERO_MODE && level < SPEC_LEVEL && !S.allSpecs) return startSpec(c.cls);
  return sp && cl.specs[sp] ? sp : cl.def;
}

edits.old:
function specKey(k) {
  const g = tavRec(k), c = B.CLASSES[clsOf(k)]; if (!c) return null;
  if (g) return g.sp;
  return c.specs[S.specs[k]] ? S.specs[k] : c.def;
}

edits.new:
function specKey(k) {
  const cls = clsOf(k), c = B.CLASSES[cls]; if (!c) return null;
  if (ARMS_HERO_MODE && !canSpecialize(k)) return cls === 'warrior' ? 'arms' : startSpec(cls);
  return selectedSpec(k);
}
